section.programlisting:
static final LayerKey<Integer> TOKEN_LENGTHS =
    LayerKey.of("token-lengths", Integer.class);

class TokenLengthAnnotator implements DocumentAnnotator {

  @Override
  public Document annotate(Document document) {
    DocumentAnnotators.requireLayers(document, Layers.TOKENS);
    List<Annotation<String>> tokens = document.get(Layers.TOKENS);
    List<Annotation<Integer>> lengths = new ArrayList<>(tokens.size());
    for (Annotation<String> token : tokens) {
      lengths.add(new Annotation<>(token.span(), token.value().length()));
    }
    return document.with(TOKEN_LENGTHS, lengths);
  }

  @Override
  public Set<LayerKey<?>> requires() {
    return Set.of(Layers.TOKENS);
  }

  @Override
  public Set<LayerKey<?>> provides() {
    return Set.of(TOKEN_LENGTHS);
  }
}


DocumentAnnotator guarded =
    new ConditionalAnnotator(d -> d.text().length() >= 20, new TokenLengthAnnotator());
// A short document has the output layer, with no annotations.


LayerKey<Integer> SELECTED_LENGTHS =
    LayerKey.of("token-lengths-selected", Integer.class);

DocumentAnnotator selected = new ConditionalAnnotator(
    d -> d.text().length() >= 20,
    new FilterAnnotator<>(TOKEN_LENGTHS, SELECTED_LENGTHS, a -> a.value() >= 5),
    new FilterAnnotator<>(TOKEN_LENGTHS, SELECTED_LENGTHS, a -> a.value() < 5));


LayerKey<Integer> SELECTED_LENGTHS =
    LayerKey.of("token-lengths-selected", Integer.class);

DocumentAnnotator filter =
    new FilterAnnotator<>(TOKEN_LENGTHS, SELECTED_LENGTHS, a -> a.value() >= 5);
// SELECTED_LENGTHS contains 6 and 5. TOKEN_LENGTHS still contains all five values.


LayerKey<String> NORMALIZED_WORDS =
    LayerKey.of("normalized-words", String.class);
LayerKey<String> CAPITALIZED_WORDS =
    LayerKey.of("capitalized-words", String.class);

DocumentAnnotator capitalized = new FilterAnnotator<>(
    NORMALIZED_WORDS, CAPITALIZED_WORDS,
    (document, word) -> {
      Span span = word.span();
      if (span.length() == 0) {
        return false;
      }
      int initial = Character.codePointAt(document.text(), span.getStart());
      return Character.charCount(initial) <= span.length() && Character.isUpperCase(initial);
    });
